  assert.deepEqual(await h.order('a'), { status: 'failed', items: 2, charges: 2, refunds: 0, held: false });
  assert.deepEqual(await h.order('b'), { status: 'paid', items: 2, charges: 2, refunds: 0, held: false });
  assert.equal((await h.retryPayment('a')).ok, false);
  assert.equal((await h.cancel('b')).ok, true);
  assert.equal((await h.order('b'))!.refunds, 1);
  assert.equal((await h.retryPayment('zz')).ok, false);
});

test('cancel while placed: refund only if the charge went through', async () => {
  const h = await createHost();
  for (const id of ['a', 'b', 'c']) { await h.create(id); await h.addItem(id); await h.place(id); }
  for (const id of ['a', 'b']) {
    assert.equal((await h.cancel(id)).ok, true);
    assert.deepEqual(await h.order(id), { status: 'cancelling', items: 1, charges: 1, refunds: 0, held: false });
    for (const cmd of ['addItem', 'removeItem', 'place', 'ship', 'cancel', 'retryPayment'] as const) {
      assert.equal((await h[cmd](id)).ok, false, cmd);
    }
  }
  const effs = await h.pendingEffects();
  await h.completeEffect(effs.find((e) => e.from === 'a')!.id, 'ok');
  await h.completeEffect(effs.find((e) => e.from === 'b')!.id, 'failed');
  assert.deepEqual(await h.order('a'), { status: 'cancelled', items: 1, charges: 1, refunds: 1, held: false });
  assert.deepEqual(await h.order('b'), { status: 'cancelled', items: 1, charges: 1, refunds: 0, held: false });
  // cancelling during the retry charge
  await h.completeEffect(effs.find((e) => e.from === 'c')!.id, 'failed');
  await h.retryPayment('c');
  assert.equal((await h.cancel('c')).ok, true);
  await h.completeEffect((await h.pendingEffects())[0].id, 'failed');
  assert.deepEqual(await h.order('c'), { status: 'cancelled', items: 1, charges: 2, refunds: 0, held: false });
  assert.deepEqual(await h.pendingEffects(), []);
});
